import {escapeHTML,plural,button,iconButton} from './primitives.js?v=89';
import {itemPreview,pieceSVG} from '../pieces.js?v=89';
import {craftCost,itemById,PIECE_NAMES,rarityNames} from '../catalog.js?v=89';
import {dayLabel} from '../activity.js?v=89';
const exportIcon = path => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`;
export const exportPgnDialog = pgn => `<h2 tabindex="-1" autofocus>Экспорт партии</h2><textarea id="pgn-text" class="pgn-text" aria-label="PGN партии" readonly>${escapeHTML(pgn)}</textarea><div class="pgn-actions">${iconButton({label:'Скачать PGN',icon:exportIcon('M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5'),'data-download-pgn':true})}${iconButton({label:'Скопировать PGN',icon:exportIcon('M9 9h11v11H9zM15 9V4H4v11h5'),'data-copy-pgn':true})}${iconButton({label:'Поделиться PGN',icon:exportIcon('M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8'),'data-share-pgn':true})}</div><p id="pgn-feedback" class="pgn-feedback" role="status" aria-live="polite"></p>`;
export const importPgnDialog = () => '<h2 tabindex="-1" autofocus>Открыть PGN</h2><div class="pgn-import-actions"><button type="button" class="quiet" data-pgn-paste>Вставить текст</button><button type="button" class="quiet" data-pgn-file>Выбрать файл</button></div><input id="pgn-file" type="file" accept=".pgn,text/plain,application/x-chess-pgn" hidden><form id="import-pgn-form" hidden><label for="import-pgn-text">PGN партии</label><textarea id="import-pgn-text" class="pgn-text" placeholder="Вставьте текст партии" spellcheck="false" required></textarea><button type="submit" class="primary wide">Открыть</button></form><p id="pgn-import-error" role="alert" class="pgn-feedback"></p>';
export const cancelledDialog = () => '<h2>Партия отменена</h2><p>Вы не сделали ни одного хода, поэтому партия не попала в историю и статистику и не принесла награду.</p>';
export const matchResultDialog = (title,reward,entry,breakdown,reason='') => `<h2>${escapeHTML(entry?.result||title)}</h2>${reason?`<p class="match-end-reason">${escapeHTML(reason)}</p>`:''}<p class="reward-total">+${reward} ${plural(reward,['монета','монеты','монет'])}</p>${breakdown?`<dl class="reward-breakdown"><div><dt>Партия завершена</dt><dd>+${breakdown.completion}</dd></div><div><dt>Результат партии</dt><dd>+${breakdown.result}</dd></div>${breakdown.qualityDetails?['accuracy','stability','best'].map((key,i)=>`<div><dt>${['Точность','Стабильность','Лучшие решения'][i]}</dt><dd>+${breakdown.qualityDetails[key]}</dd></div>`).join(''):`<div><dt>Качество решений</dt><dd>${breakdown.qualityStatus==='pending'?'Считаем…':`+${breakdown.quality||0}`}</dd></div>`}</dl>${breakdown.qualityStatus==='pending'?'<p id="reward-quality-progress" class="reward-note" role="status">Оцениваем качество ходов…</p><p class="reward-note">Можно продолжить: бонус начислится после анализа.</p>':''}${breakdown.qualityStatus==='fallback'?'<p class="reward-note">Не удалось оценить качество после повторных попыток. Начислен резервный бонус: 5 монет.</p>':''}${breakdown.reason==='early-resignation'?'<p class="reward-note">За эту партию монеты не начислены: сдача до 10 собственных ходов.</p>':''}`:''}`;
export const botFailureDialog = () => '<h2>ИИ не смог сделать ход</h2><p>Повторите расчёт или завершите партию без изменения прогресса. История ходов сохранится.</p><button class="quiet" data-retry-bot>Повторить расчёт</button><button class="quiet" data-export-pgn>Экспортировать PGN</button><button class="quiet" data-abort-failed>Отменить партию</button>';
export const promotionDialog = (color,equipped) => `<h2>Во что превратить пешку?</h2><div class="promotion">${['q','r','b','n'].map(type=>`<button data-promote="${type}" aria-label="${PIECE_NAMES[type]}">${pieceSVG(type,color,itemById(equipped.pieces[type]).style)}</button>`).join('')}</div>`;
export const craftDialog = (item,id) => `<div class="result-art">${itemPreview(item)}</div><h2>${item.name}</h2><p>Создать за ${craftCost(item)} ${plural(craftCost(item),['осколок','осколка','осколков'])}?</p><button class="primary" data-confirm-craft="${id}">Создать за ${craftCost(item)} ✧</button>`;
export const saveSetDialog = () => '<h2>Сохранить набор</h2><p>В набор войдут шесть выбранных фигур и текущая доска.</p><form id="save-set-form"><label for="set-name">Название</label><input id="set-name" name="name" maxlength="32" required placeholder="Например, Полярная ночь" autocomplete="off"><button class="primary" type="submit">Сохранить набор</button></form>';
export const activityDialog = (event) => `<div class="calendar-day closed today day-closed-mark" aria-label="Серия: ${dayLabel(event.streak)}">${event.streak}</div><h2>${event.streak===1?'Серия началась':'Серия продолжается'}</h2><strong class="streak-value">${dayLabel(event.streak)}${event.streak>1?' подряд':''}</strong>`;
export const chestRewardDialog = (title,artwork,item,shards,copy,duplicate) => `<p class="eyebrow">${title}</p><div class="result-art reveal${item&&['epic','legendary'].includes(item.rarity)?` reward-${item.rarity}`:''}">${artwork}</div>${item?`<span class="rarity ${item.rarity}">${rarityNames[item.rarity]}</span><h2>${item.name}</h2>`:''}${shards?`<h2>+${shards} ${plural(shards,['осколок','осколка','осколков'])}</h2>`:''}<p>${copy}</p>${item&&!duplicate?`<div class="chest-reward-actions"><button class="primary" data-use-reward="${item.id}">Использовать</button><button class="quiet" data-view-reward="${item.id}">В коллекцию</button></div>`:''}`;
export const resignDialog = () => `<h2>Сдаться?</h2><p>До вашего первого хода партия просто отменится. После первого хода сдача считается поражением. Награда начисляется по правилам завершённой партии.</p>${button({variant:'danger',label:'Сдаться','data-confirm-resign':true})}`;
export const installHelpDialog = () => '<h2>Установить GachaChess</h2><p>На iPhone: откройте сайт в Safari → «Поделиться» → «На экран Домой».</p><p>На Android и компьютере: в меню браузера выберите «Установить приложение».</p><p>После первой загрузки игру можно запускать без интернета.</p>';

export const deleteSetDialog = id => `<h2>Удалить набор?</h2><p>Все предметы останутся в коллекции.</p>${button({variant:'danger',label:'Удалить набор','data-confirm-delete-set':id})}`;
